# Fonction pour convertir une chaîne binaire de 24 bits en 3 caractères ASCII
def decode_binary_string(bin_str):
    chars = []
    for i in range(0, 24, 8):
        byte = bin_str[i:i+8]
        decimal = int(byte, 2)
        chars.append(chr(decimal))
    return ''.join(chars)

